function normalizeState(input={}){const loaded={...structuredClone(DEFAULT),...input};if(loaded.view==='palette')loaded.view='home';loaded.schemaVersion=2;loaded.completions=[...new Set(Array.isArray(loaded.completions)?loaded.completions.map(Number).filter(n=>n>=1&&n<=80):[])].sort((a,b)=>a-b);loaded.audioCompleted=[...new Set(Array.isArray(loaded.audioCompleted)?loaded.audioCompleted.map(Number).filter(n=>n>=1&&n<=80):[])].sort((a,b)=>a-b);loaded.audioPositions=loaded.audioPositions&&typeof loaded.audioPositions==='object'?loaded.audioPositions:{};loaded.decisions=loaded.decisions&&typeof loaded.decisions==='object'?loaded.decisions:{};loaded.scenarioOutcomes=loaded.scenarioOutcomes&&typeof loaded.scenarioOutcomes==='object'?loaded.scenarioOutcomes:{};loaded.capstones=loaded.capstones&&typeof loaded.capstones==='object'?loaded.capstones:{};loaded.domains={...structuredClone(DEFAULT.domains),...(loaded.domains&&typeof loaded.domains==='object'?loaded.domains:{})};loaded.intake={...structuredClone(DEFAULT.intake),...(loaded.intake&&typeof loaded.intake==='object'?loaded.intake:{})};loaded.checklist={...structuredClone(DEFAULT.checklist),...(loaded.checklist&&typeof loaded.checklist==='object'?loaded.checklist:{})};loaded.retrieval={...structuredClone(DEFAULT.retrieval),...(loaded.retrieval&&typeof loaded.retrieval==='object'?loaded.retrieval:{})};loaded.retrieval.answers=loaded.retrieval.answers&&typeof loaded.retrieval.answers==='object'?loaded.retrieval.answers:{};loaded.retrieval.reviewed=loaded.retrieval.reviewed&&typeof loaded.retrieval.reviewed==='object'?loaded.retrieval.reviewed:{};loaded.advisorSaved=Array.isArray(loaded.advisorSaved)?loaded.advisorSaved.slice(-80):[];loaded.masteryUnlocked=Boolean(loaded.masteryUnlocked||loaded.completions.includes(60));return loaded}
function mergeProgress(local,remote){const merged=normalizeState({...local,...remote});merged.completions=[...new Set([...(local.completions||[]),...(remote.completions||[])])].sort((a,b)=>a-b);merged.audioCompleted=[...new Set([...(local.audioCompleted||[]),...(remote.audioCompleted||[])])].sort((a,b)=>a-b);merged.currentDay=Math.max(Number(local.currentDay||1),Number(remote.currentDay||1));merged.streak=Math.max(Number(local.streak||0),Number(remote.streak||0));merged.tier=(local.tier==='mastery'||remote.tier==='mastery')?'mastery':'foundation';merged.masteryUnlocked=Boolean(local.masteryUnlocked||remote.masteryUnlocked||merged.completions.includes(60));merged.audioPositions={...(remote.audioPositions||{}),...(local.audioPositions||{})};merged.decisions={...(remote.decisions||{}),...(local.decisions||{})};merged.scenarioOutcomes={...(remote.scenarioOutcomes||{}),...(local.scenarioOutcomes||{})};merged.capstones={...(remote.capstones||{}),...(local.capstones||{})};merged.intake={...(remote.intake||{}),...(local.intake||{})};merged.checklist={...(remote.checklist||{}),...(local.checklist||{})};merged.checklistDismissed=Boolean(local.checklistDismissed||remote.checklistDismissed);merged.retrieval={answers:{...(remote.retrieval?.answers||{}),...(local.retrieval?.answers||{})},reviewed:{...(remote.retrieval?.reviewed||{}),...(local.retrieval?.reviewed||{})}};merged.advisorSaved=[...(remote.advisorSaved||[]),...(local.advisorSaved||[])].filter((item,i,a)=>item?.id&&a.findIndex(x=>x.id===item.id)===i).slice(-80);merged.domains={...(remote.domains||{})};for(const [k,v]of Object.entries(local.domains||{})){merged.domains[k]={strength:Math.max(Number(v?.strength||0),Number(merged.domains[k]?.strength||0))}}return normalizeState(merged)}
const stateStore=(()=>{let clerkClient=null,syncTimer=null,syncInFlight=false,hydrating=false,lastSaved='';function localLoad(){try{const raw=localStorage.getItem(KEY);const clean=raw?normalizeState(JSON.parse(raw)):structuredClone(DEFAULT);lastSaved=JSON.stringify(clean);return clean}catch{return structuredClone(DEFAULT)}}function localSave(next){const clean=normalizeState(next);localStorage.setItem(KEY,JSON.stringify(clean));return clean}function queued(){try{return JSON.parse(localStorage.getItem(QUEUE_KEY)||'[]')}catch{return[]}}function setQueue(items){if(items.length)localStorage.setItem(QUEUE_KEY,JSON.stringify(items.slice(-20)));else localStorage.removeItem(QUEUE_KEY)}function status(text){syncStatus(text)}function configured(){return remoteConfigured()}function api(path){return `${CONFIG.apiBaseUrl.replace(/\/$/,'')}${path}`}async function token(){try{return await clerkClient?.session?.getToken()}catch{return null}}async function authedFetch(path,options={}){const t=await token();if(!t)throw new Error('missing token');return fetch(api(path),{...options,headers:{'content-type':'application/json',...(options.headers||{}),Authorization:`Bearer ${t}`}})}function schedule(delay=1500){if(hydrating||!configured()||!clerkClient?.user)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync(),delay)}async function init(){const btn=document.getElementById('accountAction');if(!configured()){status('Progress saved locally · sign-in not configured');return}try{status('Account sync loading');const domain=clerkDomain();if(!domain)throw new Error('invalid Clerk publishable key');clerkClient=await initClerkClient(domain);if(btn){btn.hidden=false;btn.addEventListener('click',accountAction)}if(clerkClient.addListener)clerkClient.addListener(()=>{renderAccountState();if(clerkClient.user)hydrate()});renderAccountState();if(clerkClient.user)await hydrate();else status('Local demo mode · sign in to sync progress')}catch{status('Account sync unavailable · local cache active')}}function renderAccountState(){const btn=document.getElementById('accountAction');if(!btn||!configured())return;btn.hidden=false;const user=clerkClient?.user;btn.textContent=user?'Sign out':'Sign in';const label=user?.primaryEmailAddress?.emailAddress||user?.fullName||'';btn.title=label?`Signed in as ${label}`:'Sign in to sync progress'}async function accountAction(){if(!clerkClient)return;if(clerkClient.user){await sync();await clerkClient.signOut();renderAccountState();status('Signed out · local cache active');return}await clerkClient.openSignIn({afterSignInUrl:location.href,afterSignUpUrl:location.href});renderAccountState()}async function hydrate(){if(hydrating||!configured()||!clerkClient?.user)return;hydrating=true;try{status('Syncing account progress');const res=await authedFetch('/api/progress',{method:'GET'});if(!res.ok)throw new Error('progress fetch failed');const remote=await res.json();const local=state;if(remote.state){state=mergeProgress(local,remote.state);status('Account progress loaded')}else{state=normalizeState(local);status(localStorage.getItem(KEY)?'Imported local progress to account':'New account progress initialized')}activeDay=state.currentDay;state=localSave(state);lastSaved=JSON.stringify(state);render();await sync(0)}catch{status('Sync failed · local cache active')}finally{hydrating=false;renderAccountState()}}function save(next,options={}){const previous=lastSaved;state=localSave(next);lastSaved=JSON.stringify(state);if(!options.localOnly&&(lastSaved!==previous||options.force))schedule(options.delay??1500)}function patch(partial){save({...state,...partial})}async function sync(delay){if(delay!==0&&delay!==undefined){schedule(delay);return}if(syncInFlight||!configured()||!clerkClient?.user)return;syncInFlight=true;try{status('Saving progress');const items=queued();for(const item of items){await authedFetch('/api/progress/events',{method:'POST',body:JSON.stringify(item)})}setQueue([]);const res=await authedFetch('/api/progress',{method:'PUT',body:JSON.stringify({state,clientUpdatedAt:new Date().toISOString()})});if(res.status===409){const fresh=await authedFetch('/api/progress',{method:'GET'});const remote=await fresh.json();state=mergeProgress(state,remote.state||{});state=localSave(state);lastSaved=JSON.stringify(state);render()}else if(!res.ok)throw new Error('progress save failed');status('Progress synced to account')}catch{queueEvent('sync_failed',{currentDay:state.currentDay},false);status('Sync queued locally')}finally{syncInFlight=false}}function queueEvent(eventType,payload={},shouldSchedule=true){const items=queued();items.push({eventType,payload,clientUpdatedAt:new Date().toISOString()});setQueue(items);if(shouldSchedule)schedule(3000)}window.addEventListener('online',()=>sync(0));return{load:localLoad,save,patch,sync,init,queueEvent,get user(){return clerkClient?.user||null}}})();
function loadState(){return stateStore.load()}
function saveState(){stateStore.save(state)}
function syncStatus(text){const el=document.getElementById('syncStatus');if(el)el.textContent=text;updateAccountMode()}
function remoteConfigured(){return Boolean(CONFIG.apiBaseUrl&&/^pk_(test|live)_/.test(CONFIG.clerkPublishableKey||''))}
function clerkDomain(){try{return atob(CONFIG.clerkPublishableKey.split('_')[2]).slice(0,-1)}catch{return''}}
async function initClerkClient(domain){await loadScript(`https://${domain}/npm/@clerk/clerk-js@5/dist/clerk.browser.js`,{'data-clerk-publishable-key':CONFIG.clerkPublishableKey});const loaded=window.Clerk;if(typeof loaded==='function'){const client=new loaded(CONFIG.clerkPublishableKey);try{await client.load({publishableKey:CONFIG.clerkPublishableKey})}catch{await client.load()}return client}if(loaded?.load){try{await loaded.load({publishableKey:CONFIG.clerkPublishableKey})}catch{await loaded.load()}return loaded}throw new Error('Clerk unavailable')}
function loadScript(src,attrs={}){return new Promise((resolve,reject)=>{let s=document.querySelector(`script[src="${src}"]`);if(s){for(const[k,v]of Object.entries(attrs))s.setAttribute(k,v);return resolve()}s=document.createElement('script');s.src=src;s.async=true;s.crossOrigin='anonymous';for(const[k,v]of Object.entries(attrs))s.setAttribute(k,v);s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})}
state=loadState();activeDay=state.currentDay;
function day(n=activeDay){return CURRICULUM.find(d=>d.d===n)||CURRICULUM[0]}
function done(n){return state.completions.includes(n)}
function scenarioKey(d){return`day-${d.d}`}
function restoreDecisionState(d=day()){if(!d.scn){decisionIndex=0;selected=[];lastOutcome='';return}const key=scenarioKey(d),decisions=Array.isArray(state.decisions?.[key])?state.decisions[key]:[],outcomes=Array.isArray(state.scenarioOutcomes?.[key])?state.scenarioOutcomes[key]:[],count=d.scn.dec.length;selected=decisions.map(x=>Number.isInteger(x?.choiceIndex)?x.choiceIndex:null);const answered=decisions.reduce((n,x,i)=>x&&Number.isInteger(x.choiceIndex)?i+1:n,0);if(state.sub==='outcome'){decisionIndex=Math.max(0,Math.min(count-1,answered-1));lastOutcome=outcomes[decisionIndex]||lastOutcome||'';return}if(state.sub==='decision'){decisionIndex=Math.max(0,Math.min(count-1,answered));lastOutcome=outcomes[decisionIndex-1]||'';return}if(state.sub==='debrief'){decisionIndex=count;lastOutcome=outcomes[count-1]||'';return}decisionIndex=0;lastOutcome=''}
function foundationComplete(){return state.masteryUnlocked||state.completions.includes(60)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sourceSearchUrl(q){return `https://scholar.google.com/scholar?q=${encodeURIComponent(String(q||'').replace(/[“”]/g,'"').replace(/[’]/g,"'").replace(/\s+/g,' ').trim())}`}
function daySourceUrl(d){return sourceSearchUrl(`${d.cite} ${d.t} ${d.o}`)}
function readingSourceUrl(r){return sourceSearchUrl(`${r[2]} ${r[1]} ${r[3]}`)}
function sourceLink(url,label='SOURCE ↗'){return `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`}
function todayStamp(){return new Date().toISOString().slice(0,10)}
function accountMode(){if(stateStore.user)return'SIGNED-IN SYNCED MODE';if(hasAccess())return'BETA ACCESS CODE · LOCAL DEMO PROGRESS';return'LOCKED LOCAL DEMO'}
function updateAccountMode(){const el=document.getElementById('accountMode');if(el)el.textContent=accountMode()}
function sourceQualityLabel(kind,source=''){const s=String(source).toLowerCase();if(kind==='day')return s.includes('hbr')?'CANON · HBR / practitioner source':s.includes('wiley')||s.includes('prentice')||s.includes('handbook')?'CANON · book / handbook':s.includes('journal')||s.includes('sci')||s.includes('ij')||s.includes('op.')?'CANON · peer-reviewed lookup':'CANON · source lookup';if(s.includes('hbr'))return'Practitioner source';if(s.includes('journal')||s.includes('sci')||s.includes('ij')||s.includes('op.'))return'Peer-reviewed lookup';if(s.includes('book')||s.includes('wiley')||s.includes('prentice'))return'Book / handbook lookup';return'Needs verification'}
function sourceTrustCard(d){const readings=readingsForDay(d.d);return `<div class="source-trust"><div class="source-trust-row"><span class="quality">${esc(sourceQualityLabel('day',`${d.cite} ${d.o}`))}</span><span>Direct URL/DOI: needs verification</span><span>Lookup: Scholar query, not a fabricated source URL</span></div>${readings.length?`<div class="day-readings"><div class="amber">READING BACKLINKS</div>${readings.map(r=>`<button class="mini-link" data-go-day="${r.day}" type="button">${esc(r.tier)} · ${esc(r.title)}</button>`).join('')}</div>`:''}</div>`}
function intakePath(){const prefs=state.intake||DEFAULT.intake;const domainBoost={operator:[1,3,7,12],finance:[1,3,10,11],procurement:[4,5,6,8],planner:[2,3,10,13],executive:[1,9,11,13],student:[1,2,3,4]};const picks=domainBoost[prefs.role]||domainBoost.operator;const days=CURRICULUM.filter(d=>picks.includes(d.dom)).slice(0,8);return{prefs,days}}
function renderIntake(){if(state.intake?.done)return'';const {prefs,days}=intakePath();return `<section class="intake card" aria-label="Diagnostic onboarding"><div class="source-head"><div><div class="amber">FIRST-RUN PATHING</div><div class="dim">Canonical sequence stays intact. These domains get extra attention.</div></div><button class="soft tiny" data-intake="save" type="button">Save path</button></div><div class="intake-grid">${[['role','Role',[['operator','Operator'],['procurement','Procurement'],['planner','Planner'],['finance','Finance'],['executive','Executive'],['student','Student']]],['goal','Goal',[['build-fluency','Build fluency'],['prep-role','Prepare for role'],['fix-work','Apply at work']]],['experience','Experience',[['new','New'],['working','Working'],['advanced','Advanced']]],['industry','Industry',[['food','Food/CPG'],['retail','Retail'],['manufacturing','Manufacturing'],['healthcare','Healthcare'],['tech','Tech']]],['timeBudget','Time',[['5','5 min/day'],['10','10 min/day'],['20','20 min/day']]]].map(([key,label,opts])=>`<label>${label}<select data-intake="${key}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${prefs[key]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`).join('')}</div><div class="path-list">${days.map(d=>`<button class="mini-link" data-go-day="${d.d}" type="button">Day ${d.d} · ${esc(d.t)}</button>`).join('')}</div></section>`}
function renderChecklist(){if(state.checklistDismissed||state.completions.length>2)return'';const d=day(),c=state.checklist||{};const items=[['listen','Listen',state.audioCompleted.includes(d.d)||c.listen],['case','Answer case',(!d.scn||state.sub==='debrief'||done(d.d)||c.case)],['source','Review source',c.source],['advisor','Ask Advisor',c.advisor],['complete','Complete day',done(d.d)||c.complete]];return `<section class="checklist card"><div class="source-head"><div class="amber">DAY ONE CHECKLIST</div><button class="soft tiny" data-check-dismiss type="button">Dismiss</button></div><div class="check-grid">${items.map(([k,l,on])=>`<button class="${on?'checked':''}" data-check="${k}" type="button">${on?'✓':'□'} ${esc(l)}</button>`).join('')}</div></section>`}
function retrievalQuestions(d){return[{id:'framework',q:`Name the framework for Day ${d.d}.`,hint:d.f},{id:'plain',q:'Explain it in plain English.',hint:d.sum},{id:'apply',q:'What Monday-morning decision does it change?',hint:d.scn?.fr||d.sum}]}
function retrievalKey(dayNum,id){return `${todayStamp()}:day-${dayNum}:${id}`}
function renderRetrieval(d){const prior=[...new Set([d.d-1,d.d-3,d.d-7].filter(n=>n>0&&state.completions.includes(n)))].map(n=>day(n));const cards=[...retrievalQuestions(d).map(x=>({day:d.d,...x,type:'today'})),...prior.map(p=>({day:p.d,id:'review',q:`Spaced review: ${p.t}`,hint:`${p.f} · ${p.sum}`,type:'review'}))].slice(0,6);return `<section class="retrieval card"><div class="amber">RETRIEVAL LOOP</div><div class="dim">Answer from memory, then reveal the source hint.</div>${cards.map(c=>{const key=retrievalKey(c.day,c.id),saved=state.retrieval.answers[key];return `<div class="retrieval-card ${saved?'answered':''}"><div class="source-head"><div><span class="tier ${c.type==='review'?'emerging':'core'}">${c.type==='review'?'SPACED':'TODAY'}</span><span>${esc(c.q)}</span></div><button class="soft tiny" data-retrieval="${esc(key)}" data-day-ref="${c.day}" data-hint="${esc(c.hint)}" type="button">${saved?'Update':'Mark owned'}</button></div><textarea data-retrieval-answer="${esc(key)}" placeholder="Plain-English answer">${esc(saved?.answer||'')}</textarea><details><summary class="amber">Source hint</summary><p>${esc(c.hint)}</p></details></div>`}).join('')}</section>`}
function decisionScoreForDay(d){const arr=state.decisions?.[scenarioKey(d)]||[];if(!d.scn)return null;const total=d.scn.opt.length||1;const correct=arr.reduce((n,x,i)=>n+(x?.choiceIndex===d.scn.opt[i]?1:0),0);return{correct,total,missed:arr.filter((x,i)=>x&&x.choiceIndex!==d.scn.opt[i]).length}}
function domainMastery(domainNum){const days=CURRICULUM.filter(d=>d.dom===domainNum);const completed=days.filter(d=>done(d.d)).length;const decisionDays=days.filter(d=>d.scn);const decisionTotal=decisionDays.reduce((n,d)=>n+(d.scn?.opt.length||0),0);const decisionCorrect=decisionDays.reduce((n,d)=>n+(state.decisions?.[scenarioKey(d)]||[]).reduce((m,x,i)=>m+(x?.choiceIndex===d.scn.opt[i]?1:0),0),0);const retrievalHits=Object.values(state.retrieval.answers||{}).filter(x=>days.some(d=>d.d===Number(x.day))).length;const base=days.length?(completed/days.length)*55:0;const decisions=decisionTotal?(decisionCorrect/decisionTotal)*30:0;const retrieval=Math.min(15,retrievalHits*3);return Math.round(Math.min(100,base+decisions+retrieval))}
function principalMap(){const rows=DOMAINS.map(d=>({domain:d,score:domainMastery(d.n)}));const weak=[...rows].sort((a,b)=>a.score-b.score).slice(0,3);const strong=[...rows].sort((a,b)=>b.score-a.score).slice(0,3);return `<section class="principal-map card"><div class="amber">PRINCIPAL'S MAP</div><div class="map-grid">${rows.map(({domain,score})=>`<div class="vu-mini"><span>${esc(domain.name.slice(0,5))}</span><div class="bar"><div class="fill" style="width:${score}%"></div></div><span>${score}</span></div>`).join('')}</div><div class="evidence-grid"><div><div class="green-bold">Strengths</div>${strong.map(x=>`<p>${esc(x.domain.name)} · ${x.score}</p>`).join('')}</div><div><div class="amber">Weak domains</div>${weak.map(x=>`<p>${esc(x.domain.name)} · ${x.score}</p>`).join('')}</div><div><div class="green-bold">Evidence</div><p>${state.completions.length} completions · ${Object.keys(state.decisions||{}).length} case days · ${Object.keys(state.retrieval.answers||{}).length} retrieval notes · ${state.advisorSaved.length} Advisor saves</p></div></div></section>`}
function missedDecisions(){return CURRICULUM.filter(d=>d.scn).flatMap(d=>(state.decisions?.[scenarioKey(d)]||[]).map((x,i)=>x&&x.choiceIndex!==d.scn.opt[i]?{day:d.d,title:d.t,q:d.scn.dec[i].q,choice:x.choice,correct:d.scn.dec[i].o[d.scn.opt[i]]?.l}:null).filter(Boolean))}
function renderReview(){const saved=state.advisorSaved||[],missed=missedDecisions();lcd.innerHTML=`<div class="title">REVIEW DECK</div><div class="meta">MASTERY · MISSED CASES · SAVED ADVISOR NOTES</div>${principalMap()}<div class="card"><div class="amber">MISSED DECISIONS</div>${missed.length?missed.map(m=>`<div class="review-row"><button class="mini-link" data-go-day="${m.day}" type="button">Day ${m.day}</button><div><div class="green-bold">${esc(m.title)}</div><p>${esc(m.q)}</p><p class="dim">You chose: ${esc(m.choice)} · Target: ${esc(m.correct)}</p></div></div>`).join(''):'<p>No missed recorded decisions yet.</p>'}</div><div class="card"><div class="amber">SAVED ADVISOR ITEMS</div>${saved.length?saved.slice().reverse().map(item=>`<div class="review-row"><button class="mini-link" data-go-day="${item.day}" type="button">Day ${item.day}</button><div><div class="green-bold">${esc(item.kind)}</div><p>${esc(item.text)}</p><p class="dim">${esc(item.createdAt||'')}</p></div></div>`).join(''):'<p>No saved Advisor notes yet.</p>'}</div>`}
function saveAdvisorItem(kind,text){const d=day();state.advisorSaved.push({id:`${Date.now()}-${Math.random().toString(16).slice(2)}`,kind,day:d.d,title:d.t,text,createdAt:new Date().toISOString()});state.advisorSaved=state.advisorSaved.slice(-80);state.checklist.advisor=true;stateStore.queueEvent('advisor_saved',{day:d.d,kind});saveState();syncStatus(`${kind} saved to Review deck`)}
function advisorBrief(){const d=day();return `${d.t}: ${d.f}. ${d.sum} Source: ${d.cite}. Principal move: ${d.scn?.fr||'Explain the tradeoff, name the owner, and state the trigger that would change the answer.'}`}
function compactText(value,max=170){return String(value??'').replace(/\s+/g,' ').trim().slice(0,max)||'-'}
function updateAdvisorDebug(patch={}){advisorDebugState={...advisorDebugState,...patch};if(advisorHeard)advisorHeard.textContent=compactText(advisorDebugState.heard,110);if(advisorAnswer)advisorAnswer.textContent=compactText(advisorDebugState.answer,130);if(advisorTrail)advisorTrail.textContent=compactText(advisorDebugState.trail,150)}
function advisorTraceEvent(event){if(!event||!event.type)return;const trail=event.error?.message?`ERROR ${event.error.message}`:event.type;if(event.type.includes('transcription')||event.type.includes('input_audio')){const heard=event.transcript||event.text||event.delta;if(heard)updateAdvisorDebug({heard,trail});else updateAdvisorDebug({trail})}else if(event.type.includes('response')||event.type.includes('output')){const answer=event.transcript||event.text||event.delta||event.response?.status_details?.reason;if(answer)updateAdvisorDebug({answer,trail});else updateAdvisorDebug({trail})}else updateAdvisorDebug({trail})}
function advisorSessionHeaders(){const code=(new URLSearchParams(location.search).get('access')||'').trim()||(localStorage.getItem(ACCESS_KEY)==='1'?'CANON80':'');return code?{'X-SCFC-Access':code}:{}}
function advisorMicConstraints(){return{audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true,channelCount:1,sampleRate:24000}}}
function advisorMicError(err){if(err?.name==='NotAllowedError')return'Microphone permission was blocked. Allow mic access and reopen Advisor.';if(err?.name==='NotFoundError')return'No microphone was found on this device.';if(err?.name==='NotReadableError')return'Microphone is already in use by another app.';return err?.message||'Advisor microphone unavailable. Try again.'}
const advisor=(()=>{let pc=null,dc=null,stream=null,remoteAudio=null,active=false;function setStatus(text){if(advisorStatus)advisorStatus.textContent=text;updateAdvisorDebug({trail:text})}function setLine(text){if(advisorLine)advisorLine.textContent=text}function show(open=true){if(!advisorPanel)return;advisorPanel.hidden=!open;advisorToggle?.setAttribute('aria-expanded',open?'true':'false')}function api(path){if(!CONFIG.apiBaseUrl)throw new Error('missing api base');return `${CONFIG.apiBaseUrl.replace(/\/$/,'')}${path}`}async function sessionToken(){const res=await fetch(api('/api/realtime/session?provider=openai'),{method:'GET',headers:{accept:'application/json',...advisorSessionHeaders()}});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error==='openai_not_configured'?'Advisor needs OPENAI_API_KEY on the backend.':(data.detail||data.error||'Advisor session failed.'));const value=data.value||data.client_secret?.value||data.secret?.value;if(!value)throw new Error('Advisor session did not return a client secret.');return value}async function start(){if(active)return stop();show(true);setStatus('LISTENING');setLine('Opening Advisor channel for this lesson...');try{const token=await sessionToken();stream=await navigator.mediaDevices.getUserMedia(advisorMicConstraints());pc=new RTCPeerConnection();remoteAudio=document.createElement('audio');remoteAudio.autoplay=true;pc.ontrack=e=>{remoteAudio.srcObject=e.streams[0]};stream.getTracks().forEach(track=>pc.addTrack(track,stream));dc=pc.createDataChannel('oai-events');dc.addEventListener('open',()=>{active=true;advisorToggle?.classList.add('active');setStatus('READY');setLine('Advisor is live. Ask about the current framework, case, reading, or tradeoff.');sendContext('The learner opened ASK ADVISOR. Briefly ask what they want help with on this lesson.')});dc.addEventListener('message',handleEvent);pc.addEventListener('connectionstatechange',()=>{if(['failed','closed','disconnected'].includes(pc.connectionState))stop(pc.connectionState==='disconnected'?'DISCONNECTED':'READY')});const offer=await pc.createOffer();await pc.setLocalDescription(offer);const sdp=await fetch('https://api.openai.com/v1/realtime/calls',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/sdp'},body:offer.sdp});if(!sdp.ok)throw new Error('Realtime call failed.');await pc.setRemoteDescription({type:'answer',sdp:await sdp.text()})}catch(err){stop('ERROR');show(true);setLine(advisorMicError(err))}}function stop(status='READY'){active=false;advisorToggle?.classList.remove('active');setStatus(status);try{dc?.close()}catch{}try{pc?.close()}catch{}try{stream?.getTracks().forEach(t=>t.stop())}catch{}dc=null;pc=null;stream=null;remoteAudio=null;if(status==='READY')setLine('Advisor channel closed.')}function sendEvent(event){if(dc?.readyState==='open')dc.send(JSON.stringify(event))}function sendPrompt(text){show(true);if(!active){setLine('Open ASK ADVISOR first, then use this control.');return}sendContext(text)}function sendContext(text){const context=advisorContext();sendEvent({type:'conversation.item.create',item:{type:'message',role:'user',content:[{type:'input_text',text:`${text}\n\nCurrent SCFC context:\n${JSON.stringify(context)}`}]}});sendEvent({type:'response.create'})}function handleEvent(message){let event;try{event=JSON.parse(message.data)}catch{return}advisorTraceEvent(event);if(event.type==='input_audio_buffer.speech_started')setStatus('LISTENING');if(event.type==='response.created')setStatus('THINKING');if(event.type==='response.audio.delta')setStatus('SPEAKING');if(event.type==='response.done'||event.type==='response.audio.done')setStatus('READY');if(event.type==='error'){setStatus('ERROR');setLine(event.error?.message||'Advisor error. Try again.')}if(event.type==='response.function_call_arguments.done')handleToolCall(event.name,event.call_id,event.arguments);if(event.type==='response.output_item.done'&&event.item?.type==='function_call')handleToolCall(event.item.name,event.item.call_id,event.item.arguments)}function handleToolCall(name,callId,argsText){let args={};try{args=JSON.parse(argsText||'{}')}catch{}const output=advisorTool(name,args);sendEvent({type:'conversation.item.create',item:{type:'function_call_output',call_id:callId,output:JSON.stringify(output)}});sendEvent({type:'response.create'})}return{start,stop,sendPrompt}})();
function advisorContext(){const d=day();const dom=DOMAINS.find(x=>x.n===d.dom);const key=`day-${d.d}`;return{day:d.d,title:d.t,domain:dom?.name||d.dom,framework:d.f,origin:d.o,citation:d.cite,summary:d.sum,substate:state.sub,completed:done(d.d),progress:{currentDay:state.currentDay,completedCount:state.completions.length,streak:state.streak,audioCompleted:state.audioCompleted.includes(d.d)},scenario:d.scn?{title:d.scn.tp,prompt:d.scn.pre,currentDecision:d.scn.dec?.[decisionIndex]?.q||null,decisionIndex,decisionCount:d.scn.dec?.length||0,lastOutcome:lastOutcome||state.scenarioOutcomes?.[key]?.[decisionIndex]||''}:null,readings:readingsForDay(d.d)}}
function readingsForDay(n){return READING.filter(r=>r[5]===n).map(r=>({tier:r[0],author:r[1],title:r[2],source:r[3],note:r[4],day:r[5],year:r[6]||''}))}
function advisorTool(name,args={}){const d=day(Number(args.day)||activeDay);if(name==='get_current_day')return advisorContext();if(name==='get_glossary_term'){const q=String(args.query||'').toLowerCase();const hits=GLOSSARY.filter(t=>t[0].toLowerCase().includes(q)||t[1].toLowerCase().includes(q)).slice(0,6);return{query:args.query||'',hits:hits.map(t=>({term:t[0],definition:t[1]}))}}if(name==='get_readings_for_day')return{day:d.d,readings:readingsForDay(d.d)};if(name==='explain_current_framework')return{framework:d.f,title:d.t,origin:d.o,citation:d.cite,summary:d.sum,raw:d.raw};if(name==='quiz_current_day')return{day:d.d,prompt:d.scn?.dec?.[0]?.q||`Explain ${d.f} in one practical supply-chain example.`,answerHint:d.sum};return{error:'unknown_tool'}}
function advisorTools(){const dayParameter={type:'object',properties:{day:{type:'integer',minimum:1,maximum:80}},additionalProperties:false};return[{type:'function',name:'get_current_day',description:'Return the active SCFC day, framework, citation, summary, scenario, decision state, and progress context.',parameters:{type:'object',properties:{},additionalProperties:false}},{type:'function',name:'get_glossary_term',description:'Look up an SCFC glossary term by name or partial query.',parameters:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false}},{type:'function',name:'get_readings_for_day',description:'Return SCFC reading entries connected to a day.',parameters:dayParameter},{type:'function',name:'explain_current_framework',description:'Return a compact explanation target for the active day framework.',parameters:{type:'object',properties:{},additionalProperties:false}},{type:'function',name:'quiz_current_day',description:'Return a short read-only quiz prompt for the current lesson.',parameters:{type:'object',properties:{},additionalProperties:false}}]}
const voiceAdvisor=(()=>{let provider='xai',ws=null,stream=null,audioContext=null,processor=null,source=null,micMonitor=null,idleTimer=null,sessionTimer=null,playTime=0,active=false;const sampleRate=24000,advisorIdleMs=90000,advisorMaxMs=600000;function setStatus(text){if(advisorStatus)advisorStatus.textContent=text;updateAdvisorDebug({trail:text})}function setLine(text){if(advisorLine)advisorLine.textContent=text}function show(open=true){if(!advisorPanel)return;advisorPanel.hidden=!open;advisorToggle?.setAttribute('aria-expanded',open?'true':'false')}function api(path){if(!CONFIG.apiBaseUrl)throw new Error('missing api base');return `${CONFIG.apiBaseUrl.replace(/\/$/,'')}${path}`}function selectedProvider(){return String(new URLSearchParams(location.search).get('advisor')||CONFIG.advisorProvider||'xai').toLowerCase()}function clearAdvisorTimers(){clearTimeout(idleTimer);clearTimeout(sessionTimer);idleTimer=null;sessionTimer=null}function markAdvisorActivity(){if(!active)return;clearTimeout(idleTimer);idleTimer=setTimeout(()=>{stop('TIMEOUT');show(true);setLine('Advisor closed after idle time. Reopen when ready.')},advisorIdleMs)}function startAdvisorTimers(){clearAdvisorTimers();sessionTimer=setTimeout(()=>{stop('TIMEOUT');show(true);setLine('Advisor closed after the session limit. Reopen to continue.')},advisorMaxMs);markAdvisorActivity()}async function sessionInfo(){provider=selectedProvider();const res=await fetch(api(`/api/realtime/session?provider=${encodeURIComponent(provider)}`),{method:'GET',headers:{accept:'application/json',...advisorSessionHeaders()}});const data=await res.json().catch(()=>({}));if(!res.ok){const map={xai_not_configured:'Advisor needs XAI_API_KEY or GROK_API_KEY on the backend.',openai_not_configured:'Advisor needs OPENAI_API_KEY on the backend.'};throw new Error(map[data.error]||data.detail||data.error||'Advisor session failed.')}const value=data.value||data.client_secret?.value||data.secret?.value||data.client_secret||data.secret;if(!value)throw new Error('Advisor session did not return a client secret.');return{...data,value}}async function start(){provider=selectedProvider();if(provider==='openai')return advisor.start();if(active)return stop();show(true);setStatus('LISTENING');setLine('Opening Grok Advisor channel for this lesson...');try{const session=await sessionInfo();await startXai(session)}catch(err){stop('ERROR');show(true);setLine(advisorMicError(err))}}async function startXai(session){stream=await navigator.mediaDevices.getUserMedia(advisorMicConstraints());audioContext=new AudioContext({sampleRate});await audioContext.resume();playTime=audioContext.currentTime;ws=new WebSocket(session.websocketUrl||`wss://api.x.ai/v1/realtime?model=${encodeURIComponent(session.model||'grok-voice-think-fast-1.0')}`,[`xai-client-secret.${session.value}`]);ws.addEventListener('open',()=>{active=true;advisorToggle?.classList.add('active');startAdvisorTimers();setStatus('READY');setLine('Grok Advisor is live. Ask about the current framework, case, reading, or tradeoff.');sendEvent({type:'session.update',session:{voice:session.voice||'rex',instructions:advisorPrompt(),turn_detection:{type:'server_vad'},audio:{input:{format:{type:'audio/pcm',rate:sampleRate}},output:{format:{type:'audio/pcm',rate:sampleRate}}},tools:advisorTools(),tool_choice:'auto'}});wireMic();sendContext('The learner opened ASK ADVISOR. Briefly ask what they want help with on this lesson.')});ws.addEventListener('message',handleEvent);ws.addEventListener('close',()=>{if(active)stop('READY')});ws.addEventListener('error',()=>{stop('ERROR');show(true);setLine('Grok Advisor connection failed. Try again.')} )}function wireMic(){source=audioContext.createMediaStreamSource(stream);processor=audioContext.createScriptProcessor(4096,1,1);processor.onaudioprocess=e=>{if(!active||ws?.readyState!==WebSocket.OPEN)return;const input=e.inputBuffer.getChannelData(0);sendEvent({type:'input_audio_buffer.append',audio:floatToBase64Pcm16(input)})};source.connect(processor);micMonitor=audioContext.createGain();micMonitor.gain.value=0;processor.connect(micMonitor);micMonitor.connect(audioContext.destination)}function stop(status='READY'){if(provider==='openai')return advisor.stop(status);clearAdvisorTimers();active=false;advisorToggle?.classList.remove('active');setStatus(status);try{processor?.disconnect()}catch{}try{source?.disconnect()}catch{}try{micMonitor?.disconnect()}catch{}try{ws?.close()}catch{}try{stream?.getTracks().forEach(t=>t.stop())}catch{}try{audioContext?.close()}catch{}ws=null;stream=null;audioContext=null;processor=null;source=null;micMonitor=null;if(status==='READY')setLine('Advisor channel closed.')}function sendEvent(event){markAdvisorActivity();if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify(event))}function sendPrompt(text){provider=selectedProvider();if(provider==='openai')return advisor.sendPrompt(text);show(true);if(!active){setLine('Open ASK ADVISOR first, then use this control.');return}sendContext(text)}function sendContext(text){const context=advisorContext();sendEvent({type:'conversation.item.create',item:{type:'message',role:'user',content:[{type:'input_text',text:`${text}\n\nCurrent SCFC context:\n${JSON.stringify(context)}`}]}});sendEvent({type:'response.create'})}function handleEvent(message){let event;try{event=JSON.parse(message.data)}catch{return}markAdvisorActivity();advisorTraceEvent(event);if(event.type==='input_audio_buffer.speech_started')setStatus('LISTENING');if(event.type==='response.created')setStatus('THINKING');if(event.type==='response.output_audio.delta'||event.type==='response.audio.delta'){setStatus('SPEAKING');playPcm(event.delta||event.audio)}if(event.type==='response.done'||event.type==='response.output_audio.done'||event.type==='response.audio.done')setStatus('READY');if(event.type==='error'){setStatus('ERROR');setLine(event.error?.message||'Advisor error. Try again.')}if(event.type==='response.function_call_arguments.done')handleToolCall(event.name,event.call_id,event.arguments);if(event.type==='response.output_item.done'&&event.item?.type==='function_call')handleToolCall(event.item.name,event.item.call_id,event.item.arguments)}function handleToolCall(name,callId,argsText){let args={};try{args=JSON.parse(argsText||'{}')}catch{}const output=advisorTool(name,args);sendEvent({type:'conversation.item.create',item:{type:'function_call_output',call_id:callId,output:JSON.stringify(output)}});sendEvent({type:'response.create'})}function advisorPrompt(){return 'You are ASK ADVISOR, the voice tutor inside the Supply Chain Fluency Canon machine. Use concise spoken answers in practical supply-chain language. Ground answers in the SCFC lesson context and tool outputs provided by the browser. Ask one follow-up question at a time. If the user asks outside SCFC, redirect back to the current lesson, framework, reading, or decision case. Do not claim to know sources beyond loaded SCFC content.'}function floatToBase64Pcm16(float32){const pcm=new Int16Array(float32.length);for(let i=0;i<float32.length;i++){const s=Math.max(-1,Math.min(1,float32[i]));pcm[i]=s<0?s*0x8000:s*0x7fff}let binary='';const bytes=new Uint8Array(pcm.buffer);for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);return btoa(binary)}function playPcm(base64){if(!base64||!audioContext)return;const binary=atob(base64);const pcm=new Int16Array(binary.length/2);for(let i=0;i<pcm.length;i++)pcm[i]=binary.charCodeAt(i*2)|(binary.charCodeAt(i*2+1)<<8);const buffer=audioContext.createBuffer(1,pcm.length,sampleRate);const out=buffer.getChannelData(0);for(let i=0;i<pcm.length;i++)out[i]=pcm[i]/32768;const node=audioContext.createBufferSource();node.buffer=buffer;node.connect(audioContext.destination);const now=audioContext.currentTime;playTime=Math.max(playTime,now);node.start(playTime);playTime+=buffer.duration}return{start,stop,sendPrompt}})();
function render(){restoreDecisionState(day());updateAccountMode();document.body.classList.remove('notebook-menu-open');document.querySelectorAll('.modes button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));renderTier();renderMeters();if(['glos','read','review'].includes(state.view)){stopSpeech(false);audioElement.pause();audioDeck.hidden=true}else{audioDeck.hidden=false;loadEpisode(activeDay)}if(state.view==='home')renderHome();if(state.view==='curr')renderCurr();if(state.view==='review')renderReview();if(state.view==='glos')renderGloss();if(state.view==='read')renderRead();const d=day();const hidePrimary=state.view==='home'&&d.scn&&state.sub==='decision';primary.textContent=primaryLabel();primary.hidden=hidePrimary;primary.setAttribute('aria-hidden',hidePrimary?'true':'false');saveState()}
function renderTier(){document.getElementById('tierFoundation').classList.toggle('active',state.tier==='foundation');const m=document.getElementById('tierMastery');m.classList.toggle('active',state.tier==='mastery');m.classList.toggle('locked',!foundationComplete());m.textContent=(foundationComplete()?'':'▦ ')+'MAST·+20'}
function renderMeters(){document.getElementById('metersMini').innerHTML=DOMAINS.map(d=>{const s=domainMastery(d.n);return `<div class="vu-mini"><span>${esc(d.name.slice(0,5))}</span><div class="bar"><div class="fill" style="width:${s}%"></div></div><span>${s}</span></div>`}).join('')}
function header(d){const dom=DOMAINS.find(x=>x.n===d.dom)?.name||'';const cap=d.cap?` · CAPSTONE · ~${d.dur} min`:'';return `<div class="meta">DAY ${d.d} / 80${cap}</div><div class="title">${esc(d.t)}</div><div class="divider">━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</div><div class="dim">${esc(dom)} · ${esc(d.f)} · ${esc(d.o)}</div>`}
function renderHome(){const d=day();let html=renderIntake()+renderChecklist()+header(d)+`<div class="card"><div class="source-head"><div class="green-bold">CITATION</div>${sourceLink(daySourceUrl(d),'SCHOLAR LOOKUP ↗')}</div><p>${esc(d.cite)}</p>${sourceTrustCard(d)}<div class="green-bold">SUMMARY</div><p>${esc(d.sum)}</p></div>`+renderRetrieval(d);if(d.scn){if(state.sub==='briefing')html+=renderBrief(d);if(state.sub==='decision')html+=renderDecision(d);if(state.sub==='outcome')html+=`<div class="card ${lastOutcome.includes('correct')?'green-bold':'amber'}">${esc(lastOutcome)}</div>`;if(state.sub==='debrief')html+=renderDebrief(d)}else{html+=`<div class="card"><div class="green-bold">LECTURE BRIEF</div><p>${esc(d.raw)}</p></div>`}if(d.scn?.qt)html+=renderQuant(d.scn.qt);if(d.deriv)html+=renderDeriv(d.deriv);html+=`<details><summary class="amber">SOURCE BLOCK · ADVISOR SHOULD GROUND ANSWERS HERE</summary><pre class="raw-spec">${esc(d.raw)}</pre></details>`;lcd.innerHTML=html}
function renderBrief(d){const s=d.scn;return `<div class="card"><div class="green-bold">${esc(s.tp)}</div><p>${esc(s.pre)}</p>${s.sl.map(l=>`<div class="${esc(l[1])}">${esc(l[0]||' ')}</div>`).join('')}<table>${s.ctx.map(r=>`<tr><td class="amber">${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join('')}</table></div>`}
function renderDecision(d){const dec=d.scn.dec[decisionIndex];if(!dec)return renderDebrief(d);return `<div class="card"><div class="amber">${esc(dec.p)}</div><h3>${esc(dec.q)}</h3>${dec.o.map((o,i)=>`<button class="choice ${esc(o.v)}" data-choice="${i}">${esc(o.l)}</button>`).join('')}</div>`}
function renderDebrief(d){return `<div class="card"><div class="green-bold">PRINCIPAL FRAMING</div><p>${esc(d.scn?.fr||'')}</p></div>`}
function notebookPanel(d){if(state.sub==='briefing'||!d.scn)return'';let body='';let action='';if(state.sub==='decision'){body=renderDecision(d);action='<button class="panel-action" data-notebook-action="close-case" type="button">Back to notebook</button>'}else if(state.sub==='outcome'){body=`<div class="card"><div class="amber">DECISION FEEDBACK</div><p>${esc(lastOutcome||'Decision recorded.')}</p></div>`;action='<button class="panel-action" data-notebook-action="continue-case" type="button">Next decision</button>'}else if(state.sub==='debrief'){body=renderDebrief(d);action='<button class="panel-action" data-notebook-action="continue-case" type="button">Complete day</button>'}return `<section class="notebook-panel" aria-label="Decision scenario"><button class="panel-close" data-notebook-action="close-case" type="button" aria-label="Close scenario">×</button>${body}<div class="panel-actions">${action}</div></section>`}
function renderQuant(q){return `<div class="quant"><div class="amber">QUANT PANEL</div><pre>${esc(q.raw||q.f||'')}</pre><div class="green-bold">${esc(q.r||'')}</div></div>`}
function renderDeriv(deriv){return `<div class="deriv"><div class="dh">DERIVATION</div>${(deriv.steps||[]).map(st=>`<div class="step"><div class="sn">${esc(st.n)}</div><div class="stitle">${esc(st.title)}</div><div class="sbody">${esc(st.body)}</div>${st.math?`<pre class="smath">${esc(st.math)}</pre>`:''}</div>`).join('')}</div>`}
function originLine(d){return String(d.o||'').replace(/\s*\([^)]*\)\s*/g,'').replace(/;.*$/,'').trim()||d.o||''}
function articleTitle(t){return /^the\b/i.test(t)?t:`THE ${t}`}
function domainReached(d){return d.d<=state.currentDay||state.completions.includes(d.d)}
function wavyUnderlineSvg(){return `<svg class="fn-underline" viewBox="0 0 280 18" aria-hidden="true"><path d="M4 7 C42 2, 72 13, 112 7 S190 3, 276 8"/><path d="M6 13 C46 9, 84 16, 128 12 S208 9, 274 13"/></svg>`}
function coffeeStainSvg(){return `<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="cgrad1" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="rgba(107,68,35,0.05)"/><stop offset="55%" stop-color="rgba(107,68,35,0.18)"/><stop offset="72%" stop-color="rgba(74,40,15,0.55)"/><stop offset="84%" stop-color="rgba(58,28,10,0.78)"/><stop offset="92%" stop-color="rgba(74,40,15,0.55)"/><stop offset="100%" stop-color="rgba(107,68,35,0)"/></radialGradient><radialGradient id="cgrad2" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="rgba(107,68,35,0.05)"/><stop offset="50%" stop-color="rgba(107,68,35,0.20)"/><stop offset="75%" stop-color="rgba(74,40,15,0.45)"/><stop offset="92%" stop-color="rgba(58,28,10,0.55)"/><stop offset="100%" stop-color="rgba(107,68,35,0)"/></radialGradient></defs><circle cx="100" cy="100" r="92" fill="url(#cgrad1)"/><ellipse cx="105" cy="98" rx="65" ry="60" fill="url(#cgrad2)"/><circle cx="100" cy="100" r="55" fill="rgba(107,68,35,0.10)"/><path d="M 165 38 Q 175 55 170 72 Q 152 60 158 40 Z" fill="rgba(74,40,15,0.55)"/><ellipse cx="22" cy="105" rx="5" ry="8" fill="rgba(74,40,15,0.5)"/><ellipse cx="183" cy="78" rx="4" ry="6" fill="rgba(74,40,15,0.55)"/><ellipse cx="120" cy="6" rx="3" ry="5" fill="rgba(74,40,15,0.5)"/><circle cx="183" cy="125" r="5" fill="rgba(74,40,15,0.45)"/><circle cx="142" cy="184" r="6" fill="rgba(74,40,15,0.5)"/><circle cx="48" cy="28" r="3" fill="rgba(74,40,15,0.4)"/><circle cx="25" cy="180" r="4" fill="rgba(74,40,15,0.45)"/><circle cx="190" cy="160" r="2.5" fill="rgba(74,40,15,0.45)"/><circle cx="60" cy="6" r="2" fill="rgba(74,40,15,0.4)"/></svg>`}
function citationUnderlineSvg(){return `<svg class="fn-cite-line" viewBox="0 0 220 10" aria-hidden="true"><path d="M2 6 C44 1, 74 9, 120 5 S178 3, 218 6"/></svg>`}
function ticketSvg(){return `<svg class="fn-ticket-shape" viewBox="0 0 360 96" aria-hidden="true"><path d="M18 10 C44 5, 78 9, 112 7 C176 4, 231 5, 344 9 C352 23, 348 36, 356 48 C347 58, 354 74, 343 87 C270 90, 201 87, 126 90 C75 92, 38 87, 16 88 C9 70, 14 59, 5 48 C16 36, 8 23, 18 10Z"/><path class="stitch" d="M26 21 C84 16, 163 19, 232 17 C279 16, 316 19, 334 21 M25 76 C102 80, 185 76, 334 76"/></svg>`}
function miniMatrixSvg(){return `<svg class="fn-mini-matrix" viewBox="0 0 132 110" aria-label="Kraljic 2x2 sketch"><path d="M17 7 H125 V94 H17Z"/><path d="M71 7 V94 M17 49 H125"/><text x="38" y="30">Strategic</text><text x="88" y="31">Leverage</text><text x="34" y="75">Bottleneck</text><text x="88" y="76">Non-critical</text></svg>`}
function waveformSvg(){const amps=[18,32,12,48,25,54,20,35,62,41,24,50,30,58,16,28,45,33,66,38,22,52,29,57,19,34,61,44,27,49,31,55,21,36,64,42,25,47,30,59,18,37,53,40,24,51,28,63,20,35,56,43,26,48,32,60,22,39,65,45,27,50,34,58,19,36,54,41,23,49,30,62,21,38,57,44,26,52,33,60];return `<svg viewBox="0 0 304 92" aria-hidden="true">${amps.map((a,i)=>{const x=4+i*3.75,y=46-a/2;return `<path d="M${x.toFixed(1)} ${y.toFixed(1)} C${(x+1).toFixed(1)} ${(y-1).toFixed(1)},${(x+2).toFixed(1)} ${(y+1).toFixed(1)},${(x+2.4).toFixed(1)} ${(y+a).toFixed(1)}"/>`}).join('')}<circle class="fn-wave-dot" cx="4" cy="46" r="6"/></svg>`}
function stampPlaySvg(playing){return `<svg viewBox="0 0 90 90" aria-hidden="true"><defs><path id="stampTextPath" d="M16 45a29 29 0 1 1 58 0a29 29 0 1 1 -58 0"/></defs><circle cx="45" cy="45" r="39"/><text><textPath href="#stampTextPath" startOffset="13%">PLAY AUDIO</textPath></text>${playing?'<path class="pause" d="M35 31 H42 V59 H35Z M49 31 H56 V59 H49Z"/>':'<path class="tri" d="M38 29 L62 45 L38 61Z"/>'}</svg>`}
function barsSvg(strength){const s=Math.max(0,Math.min(5,Math.round(Number(strength)||0)));return `<svg class="fn-bars" viewBox="0 0 92 54" aria-hidden="true">${[18,29,43,33,49].map((h,i)=>`<rect x="${8+i*16}" y="${50-h}" width="10" height="${h}" class="${i<s?'filled':''}"/>`).join('')}</svg>`}
function calendarSvg(){const doneSet=new Set(state.completions);let cells='';for(let i=0;i<30;i++){const day=Math.max(1,state.currentDay-29+i);cells+=`<rect x="${(i%6)*12}" y="${Math.floor(i/6)*12}" width="9" height="9" class="${doneSet.has(day)?'filled':''}"/>`}return `<svg class="fn-calendar" viewBox="0 0 72 60" aria-label="Past 30 days">${cells}</svg>`}
function todayKey(date=new Date()){return date.toISOString().slice(0,10)}
function yesterdayKey(){const d=new Date();d.setDate(d.getDate()-1);return todayKey(d)}
function bumpCompletionStreak(){const today=todayKey();if(state.lastCompletedDate===today)return;state.streak=state.lastCompletedDate===yesterdayKey()?(Number(state.streak)||0)+1:1;state.lastCompletedDate=today}
function renderCurr(){const rows=CURRICULUM.filter(d=>state.tier==='mastery'?d.d>60:d.d<=60);let wk=0;let html='';rows.forEach(d=>{if(d.w!==wk){wk=d.w;html+=`<div class="curr-week">WEEK ${wk}</div><div class="curr-days">`}html+=`<div class="curr-day ${done(d.d)?'done':''} ${d.cap?'capstone':''}" data-day="${d.d}"><div class="dnum">${d.d}${state.audioCompleted.includes(d.d)?' <span class="audio-mark">♪</span>':''}</div><div class="dtitle">${esc(d.t)}</div><div class="dom">${esc(DOMAINS.find(x=>x.n===d.dom)?.name||'')}</div></div>`;const next=rows[rows.indexOf(d)+1];if(!next||next.w!==wk)html+='</div>'});lcd.innerHTML=html}
function renderGloss(){lcd.innerHTML=`<div class="title">GLOSSARY</div><div class="meta">${GLOSSARY.length} TERMS</div><div class="grid">${GLOSSARY.map(t=>`<div class="term"><div class="amber">${esc(t[0])}</div><div>${esc(t[1])}</div></div>`).join('')}</div>`}
function renderRead(){const tiers=[...new Set(READING.map(r=>r[0]))];lcd.innerHTML=`<div class="title">READING</div><div class="meta">${READING.length} ENTRIES · FILTER WITH FIND: day:11 domain:inventory week:3 tier:core</div><div class="filter-row">${tiers.map(t=>`<button class="mini-link" data-palette-query="tier:${t.toLowerCase()}" type="button">${esc(t)}</button>`).join('')}<button class="mini-link" data-palette-query="missed" type="button">Missed decisions</button><button class="mini-link" data-palette-query="saved" type="button">Saved notes</button></div>${READING.map(r=>{const d=day(r[5]);return `<div class="read-row"><div class="source-head"><div><span class="tier ${r[0].toLowerCase()}">${esc(r[0])}</span><span class="amber">DAY ${r[5]}</span><span class="quality">${esc(sourceQualityLabel('reading',r[3]))}</span></div>${sourceLink(readingSourceUrl(r),'VERIFY ↗')}</div><div class="green-bold">${esc(r[2])}</div><div>${esc(r[1])} · ${esc(r[3])}</div><div class="dim">${esc(r[4])}${r[6]?' · '+esc(r[6]):''} · ${esc(DOMAINS.find(x=>x.n===d.dom)?.name||'')}</div><button class="mini-link" data-go-day="${r[5]}" type="button">Open Day ${r[5]}</button></div>`}).join('')}`}
function primaryLabel(){const d=day();if(state.view!=='home')return 'BACK';if(done(d.d))return d.d<80?'NEXT':'COMPLETE';if(!d.scn)return 'MARK LECTURE COMPLETE';if(state.sub==='briefing')return 'START DECISION CASE';if(state.sub==='decision')return 'SELECT AN OPTION ABOVE';if(state.sub==='outcome')return 'NEXT DECISION';if(state.sub==='debrief')return 'COMPLETE DAY';return 'CONTINUE'}
function completeDay(){const d=day();if(!done(d.d)){state.completions.push(d.d);state.completions=[...new Set(state.completions)].sort((a,b)=>a-b);state.domains[d.dom].strength=(state.domains[d.dom]?.strength||0)+ (d.scn?1:.5);state.checklist.complete=true;if(d.cap)state.capstones[d.d]={completedAt:new Date().toISOString(),title:d.t};if(d.d===60)state.masteryUnlocked=true;bumpCompletionStreak()}if(d.d===80){saveState();completionSequence()}else{state.currentDay=Math.min(80,d.d+1);activeDay=state.currentDay;state.sub='briefing';render()}}
function completionSequence(){lcd.innerHTML=`<pre class="green-bold">// program complete.\n//\n// ─────────────────────────────────\n//\n// 80 days · 18 domains · 30 frameworks\n// 14 cases · 8 capstones · 80 glossary terms\n// 40+ canonical citations\n//\n// you have completed the foundation\n// of a supply chain masters fluency.\n//\n// the work from here is application.\n//\n// ─────────────────────────────────</pre>${principalMap()}`}
primary.addEventListener('click',()=>{const d=day();if(state.view!=='home'){state.view='home';render();return}if(done(d.d)){state.currentDay=Math.min(80,d.d+1);activeDay=state.currentDay;state.sub='briefing';render();return}if(!d.scn){completeDay();return}if(state.sub==='briefing'){state.sub='decision';render();return}if(state.sub==='outcome'){decisionIndex++;state.sub=decisionIndex<d.scn.dec.length?'decision':'debrief';render();return}if(state.sub==='debrief'){completeDay();return}});
lcd.addEventListener('click',e=>{const action=e.target.closest('[data-notebook-action]');if(action){handleNotebookAction(action.dataset.notebookAction,e,action);return}if(e.target.closest('.source-link')){state.checklist.source=true;saveState();return}const go=e.target.closest('[data-go-day]');if(go){const n=Number(go.dataset.goDay);if(n>0){activeDay=n;state.currentDay=n;state.view='home';state.sub='briefing';render()}return}const pq=e.target.closest('[data-palette-query]');if(pq){openPalette();const input=document.getElementById('paletteInput');input.value=pq.dataset.paletteQuery;renderPalette(input.value);return}const saveIntake=e.target.closest('[data-intake="save"]');if(saveIntake){state.intake.done=true;stateStore.queueEvent('intake_completed',state.intake);render();return}const dismiss=e.target.closest('[data-check-dismiss]');if(dismiss){state.checklistDismissed=true;render();return}const check=e.target.closest('[data-check]');if(check){state.checklist[check.dataset.check]=!state.checklist[check.dataset.check];render();return}const retr=e.target.closest('[data-retrieval]');if(retr){const key=retr.dataset.retrieval;const ta=lcd.querySelector(`[data-retrieval-answer="${CSS.escape(key)}"]`);state.retrieval.answers[key]={day:Number(retr.dataset.dayRef),answer:(ta?.value||'Owned from memory').trim()||'Owned from memory',hint:retr.dataset.hint,createdAt:new Date().toISOString()};stateStore.queueEvent('retrieval_answered',{day:Number(retr.dataset.dayRef),key});render();return}const b=e.target.closest('[data-choice]');if(!b)return;const d=day();const idx=Number(b.dataset.choice);const dec=d.scn.dec[decisionIndex];const opt=d.scn.opt[decisionIndex];selected[decisionIndex]=idx;lastOutcome=(idx===opt?'correct. ':'')+(dec.o[idx]?.c||'');const key=`day-${d.d}`;state.decisions[key]=state.decisions[key]||[];state.decisions[key][decisionIndex]={choiceIndex:idx,choice:dec.o[idx]?.l||'',correctIndex:opt,answeredAt:new Date().toISOString()};state.scenarioOutcomes[key]=state.scenarioOutcomes[key]||[];state.scenarioOutcomes[key][decisionIndex]=lastOutcome;state.checklist.case=true;stateStore.queueEvent('decision_answered',{day:d.d,decisionIndex,choiceIndex:idx,correct:idx===opt});state.sub='outcome';render()});
lcd.addEventListener('change',e=>{const el=e.target.closest('[data-intake]');if(!el||el.dataset.intake==='save')return;state.intake[el.dataset.intake]=el.value;saveState();if(lcd.querySelector('.intake'))render()});
document.querySelectorAll('.modes button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='palette'){openPalette();return}state.view=b.dataset.view;closePalette();render()}));
document.querySelectorAll('.tier-toggle button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.tier==='mastery'&&!foundationComplete()){syncStatus('Mastery +20 unlocks after completing Day 60.');return}state.tier=b.dataset.tier;render()}));
lcd.addEventListener('click',e=>{const c=e.target.closest('[data-day]');if(!c)return;const n=Number(c.dataset.day);if(n>60&&!foundationComplete())return;activeDay=n;state.currentDay=n;state.view='home';state.sub='briefing';decisionIndex=0;selected=[];render()});
function openPalette(){document.getElementById('palette').hidden=false;const input=document.getElementById('paletteInput');input.value='';input.focus();renderPalette('')}
function closePalette(){document.getElementById('palette').hidden=true}
function renderPalette(q){const raw=String(q||'').trim().toLowerCase();const filters={day:(raw.match(/\bday:(\d{1,2})/)||[])[1],week:(raw.match(/\bweek:(\d{1,2})/)||[])[1],domain:(raw.match(/\bdomain:([a-z0-9-]+)/)||[])[1],tier:(raw.match(/\btier:([a-z]+)/)||[])[1],missed:/\bmissed\b/.test(raw),saved:/\bsaved\b/.test(raw)};const text=raw.replace(/\b(day|week|domain|tier):[a-z0-9-]+/g,'').replace(/\b(missed|saved)\b/g,'').trim();const matchesText=s=>!text||String(s).toLowerCase().includes(text);const dayMatches=d=>(!filters.day||d.d===Number(filters.day))&&(!filters.week||d.w===Number(filters.week))&&(!filters.domain||(DOMAINS.find(x=>x.n===d.dom)?.name||'').toLowerCase().includes(filters.domain)||String(d.dom)===filters.domain);const items=[];if(!filters.saved&&!filters.missed)items.push(...CURRICULUM.filter(dayMatches).map(d=>({label:`Day ${d.d} · Week ${d.w} · ${DOMAINS.find(x=>x.n===d.dom)?.name}: ${d.t}`,go:()=>{activeDay=d.d;state.currentDay=d.d;state.view='home';state.sub='briefing';closePalette();render()}})).filter(x=>matchesText(x.label)));if(!filters.saved&&!filters.missed)items.push(...GLOSSARY.map(t=>({label:`Glossary · ${t[0]} — ${t[1]}`,go:()=>{state.view='glos';closePalette();render()}})).filter(x=>matchesText(x.label)));if(!filters.saved&&!filters.missed)items.push(...READING.filter(r=>{const d=day(r[5]);return dayMatches(d)&&(!filters.tier||r[0].toLowerCase()===filters.tier)}).map(r=>({label:`${r[0]} · Day ${r[5]} · ${r[2]} · ${r[1]}`,go:()=>{state.view='read';closePalette();render()}})).filter(x=>matchesText(x.label)));if(filters.missed||(!raw&&missedDecisions().length))items.push(...missedDecisions().map(m=>({label:`Missed · Day ${m.day} · ${m.q}`,go:()=>{activeDay=m.day;state.currentDay=m.day;state.view='review';closePalette();render()}})).filter(x=>matchesText(x.label)));if(filters.saved||(!raw&&state.advisorSaved.length))items.push(...(state.advisorSaved||[]).map(s=>({label:`Saved · Day ${s.day} · ${s.kind}: ${s.text}`,go:()=>{activeDay=s.day;state.currentDay=s.day;state.view='review';closePalette();render()}})).filter(x=>matchesText(x.label)));paletteIndex=0;document.getElementById('paletteResults').innerHTML=items.slice(0,50).map((x,i)=>`<div class="pal-item ${i===paletteIndex?'active':''}" data-pal="${i}">${esc(x.label)}</div>`).join('')||'<div class="pal-item">No matches. Try EOQ, day:11, domain:inventory, tier:core, missed, or saved.</div>';window.__pal=items.slice(0,50)}
function updatePaletteActive(){document.querySelectorAll('.pal-item').forEach((el,i)=>el.classList.toggle('active',i===paletteIndex));document.querySelector('.pal-item.active')?.scrollIntoView({block:'nearest'})}
function engageToday(){const d=day();if(done(d.d)){state.sub='debrief';render();return}if(!d.scn){completeDay();return}state.sub='decision';decisionIndex=0;selected=[];render()}
function seekNotebook(e,el){const rect=el.getBoundingClientRect();const pct=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));if(speechMode){speechElapsed=Math.floor(pct*speechDuration);speechIndex=0;while(speechIndex<speechBlocks.length-1&&blockStartSeconds(speechIndex+1)<speechElapsed)speechIndex++;if(currentUtterance)startSpeech();else updateSpeechUI();return}if(audioElement.duration)audioElement.currentTime=pct*audioElement.duration;updateAudioUI()}
function continueCase(){const d=day();if(state.sub==='outcome'){decisionIndex++;state.sub=decisionIndex<d.scn.dec.length?'decision':'debrief';render();return}if(state.sub==='debrief'){completeDay()}}
function handleNotebookAction(action,e,el){if(action==='curriculum'||action==='domain'||action==='stats'){state.view='curr';render();return}if(action==='engage'){engageToday();return}if(action==='continue-case'){continueCase();return}if(action==='close-case'){state.sub='briefing';render();return}if(action==='menu'){document.body.classList.toggle('notebook-menu-open');return}if(action==='play-audio'){audioPlay.click();return}if(action==='seek'){seekNotebook(e,el);return}if(action==='copy-citation'){state.checklist.source=true;saveState();navigator.clipboard?.writeText(day().cite).catch(()=>{});el.classList.add('copied');setTimeout(()=>el.classList.remove('copied'),900)}}
lcd.addEventListener('keydown',e=>{const action=e.target.closest('[data-notebook-action]');if(!action||!['Enter',' '].includes(e.key))return;e.preventDefault();handleNotebookAction(action.dataset.notebookAction,e,action)});
document.getElementById('paletteInput').addEventListener('input',e=>renderPalette(e.target.value));document.getElementById('paletteInput').addEventListener('keydown',e=>{if(!window.__pal?.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();paletteIndex=(paletteIndex+(e.key==='ArrowDown'?1:-1)+window.__pal.length)%window.__pal.length;updatePaletteActive()}if(e.key==='Enter'){e.preventDefault();window.__pal[paletteIndex]?.go()}});document.getElementById('paletteClose').addEventListener('click',closePalette);document.getElementById('paletteResults').addEventListener('click',e=>{const it=e.target.closest('[data-pal]');if(it)window.__pal[Number(it.dataset.pal)].go()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key==='Escape')closePalette();if(e.key===' '&&!e.target.matches('input, textarea')&&!audioDeck.hidden&&!audioDeck.classList.contains('disabled')){e.preventDefault();audioPlay.click()}const k=e.key.toLowerCase();if(['h','c','g','r'].includes(k)&&!e.target.matches('input, textarea')){state.view={h:'home',c:'curr',g:'glos',r:'read'}[k];render()}});
advisorToggle?.addEventListener('click',()=>voiceAdvisor.start());
advisorExplain?.addEventListener('click',()=>voiceAdvisor.sendPrompt('Explain the current SCFC framework in plain operational terms. Keep it concise.'));
advisorQuiz?.addEventListener('click',()=>voiceAdvisor.sendPrompt('Quiz me on the current SCFC day. Ask one question only.'));
document.getElementById('advisorSave')?.addEventListener('click',()=>saveAdvisorItem('Saved explanation',advisorDebugState.answer&&advisorDebugState.answer!=='-'?advisorDebugState.answer:advisorBrief()));
document.getElementById('advisorBrief')?.addEventListener('click',()=>saveAdvisorItem('One-page brief',advisorBrief()));
document.getElementById('advisorReview')?.addEventListener('click',()=>saveAdvisorItem('Review note',`Plain-English review: ${day().f} means ${day().sum}`));
advisorStop?.addEventListener('click',()=>voiceAdvisor.stop());
document.getElementById('accessPanel').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('accessCode');const code=input.value.trim().toUpperCase();const hint=document.getElementById('accessHint');if(ACCESS_CODES.has(code)){grantAccess();syncStatus('Beta access code active · progress saved locally');hint.textContent='Unlocked. Your progress will persist in this browser.';setTimeout(()=>document.querySelector('.machine')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}else{hint.textContent='That code did not unlock this copy. Try CANON80 for the current beta package.';input.select()}});
document.getElementById('resumeProgram').addEventListener('click',()=>{grantAccess();state.view='home';activeDay=state.currentDay;render();document.querySelector('.machine')?.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>{if(audioElement.paused)audioPlay.click()},300)});
document.getElementById('copyInvite').addEventListener('click',async()=>{const button=document.getElementById('copyInvite');try{await navigator.clipboard.writeText(inviteUrl());button.textContent='Invite copied'}catch{button.textContent='Code: CANON80'}setTimeout(()=>button.textContent='Copy invite link',1700)});
function formatTime(seconds){if(!isFinite(seconds))return'0:00';const m=Math.floor(seconds/60);const s=Math.floor(seconds%60);return`${m}:${String(s).padStart(2,'0')}`}
function loadEpisode(dayNum){const path=`audio/day-${String(dayNum).padStart(2,'0')}.mp3`;if(audioElement.dataset.day==dayNum)return;stopSpeech(false);audioElement.pause();audioElement.dataset.day=dayNum;audioElement.src=path;audioElement.load();speechMode=false;audioDeck.classList.remove('disabled','speech');const savedPos=state.audioPositions?.[dayNum]||0;audioElement.addEventListener('loadedmetadata',()=>{if(Number.isFinite(audioElement.duration)&&(audioElement.duration<240||audioElement.duration>420)){audioElement.pause();handleAudioUnavailable(dayNum);return}if(savedPos>0&&savedPos<audioElement.duration-5)audioElement.currentTime=savedPos;updateAudioUI()},{once:true})}
function updateAudioUI(){if(speechMode)return updateSpeechUI();const cur=audioElement.currentTime||0,dur=audioElement.duration||0,pct=dur>0?(cur/dur)*100:0;audioProgressFill.style.width=pct+'%';audioProgressHandle.style.left=pct+'%';audioTime.textContent=`${formatTime(cur)} / ${formatTime(dur)}`;audioPlay.classList.toggle('playing',!audioElement.paused);updateNotebookAudioUI()}
function updateNotebookAudioUI(){const root=document.querySelector('.view-today');if(!root)return;const cur=speechMode?speechElapsed:(audioElement.currentTime||0);const dur=speechMode?speechDuration:(audioElement.duration||0);const pct=dur>0?Math.max(0,Math.min(1,cur/dur)):0;root.querySelector('.fn-time-current').textContent=formatTime(cur);root.querySelector('.fn-time-total').textContent=formatTime(dur||((day().dur||5)*60));const liveCur=root.querySelector('.live-time-current'),liveTotal=root.querySelector('.live-time-total'),liveFill=root.querySelector('.live-audio-fill'),liveDot=root.querySelector('.live-audio-dot');if(liveCur)liveCur.textContent=formatTime(cur);if(liveTotal)liveTotal.textContent=formatTime(dur||((day().dur||5)*60));if(liveFill)liveFill.style.width=`${pct*100}%`;if(liveDot)liveDot.style.left=`${pct*100}%`;const dot=root.querySelector('.fn-wave-dot');if(dot)dot.setAttribute('cx',String(4+pct*296));const play=root.querySelector('.play-stamp');if(play){play.classList.toggle('playing',speechMode?Boolean(currentUtterance)&&!speechPaused:!audioElement.paused);play.innerHTML=stampPlaySvg(play.classList.contains('playing'))}}
function parseAudioScript(dayNum){const raw=AUDIO_SCRIPTS[String(dayNum)]||'';const parts=[];let speaker='REX',text=[];raw.split(/\n/).forEach(line=>{const tag=line.trim().match(/^\[(REX|ARA)\]$/);if(tag){if(text.join(' ').trim())parts.push({speaker,text:text.join(' ').replace(/\[pause\]/gi,' ').trim()});speaker=tag[1];text=[]}else{text.push(line)}});if(text.join(' ').trim())parts.push({speaker,text:text.join(' ').replace(/\[pause\]/gi,' ').trim()});return parts}
function naturalVoice(role){const voices=speechSynthesis.getVoices();const blocked=/zarvox|bells|bubbles|cellos|good news|bad news|boing|whisper|wobble|trinoids|jester|superstar|organ|bahh|novelty/i;const preferred=role==='ARA'?['Samantha','Moira','Karen','Shelley','Sandy','Flo','Tessa','Serena','Ava','Allison']:['Daniel','Reed','Rishi','Oliver','Tom','Alex','Eddy','Jamie','Aaron'];for(const name of preferred){const v=voices.find(x=>x.name.includes(name)&&!blocked.test(x.name));if(v)return v}return voices.find(v=>/^en[-_]/i.test(v.lang)&&!blocked.test(v.name))||voices[0]||null}
function allowSpeechFallback(){return CONFIG.enableSpeechFallback===true}
function handleAudioUnavailable(dayNum){if(allowSpeechFallback())return enableSpeechFallback(dayNum);speechMode=false;audioDeck.classList.add('disabled');audioDeck.classList.remove('speech');audioPlay.classList.remove('playing');audioTime.textContent=`DAY ${String(dayNum).padStart(2,'0')} AUDIO UNAVAILABLE`}
function enableSpeechFallback(dayNum){if(!('speechSynthesis'in window)){audioDeck.classList.add('disabled');audioTime.textContent='0:00 / 0:00';return}speechBlocks=parseAudioScript(dayNum);if(!speechBlocks.length){audioDeck.classList.add('disabled');audioTime.textContent='0:00 / 0:00';return}speechMode=true;speechIndex=0;speechElapsed=state.audioPositions?.[dayNum]||0;speechDuration=Math.max(260,Math.round(speechBlocks.reduce((n,b)=>n+b.text.split(/\s+/).filter(Boolean).length,0)/2.35));while(speechIndex<speechBlocks.length-1&&blockStartSeconds(speechIndex+1)<speechElapsed)speechIndex++;audioDeck.classList.remove('disabled');audioDeck.classList.add('speech');updateSpeechUI()}
function blockStartSeconds(index){const words=speechBlocks.slice(0,index).reduce((n,b)=>n+b.text.split(/\s+/).filter(Boolean).length,0);const total=speechBlocks.reduce((n,b)=>n+b.text.split(/\s+/).filter(Boolean).length,0)||1;return Math.round((words/total)*speechDuration)}
function updateSpeechUI(){const pct=speechDuration>0?Math.min(100,(speechElapsed/speechDuration)*100):0;audioProgressFill.style.width=pct+'%';audioProgressHandle.style.left=pct+'%';audioTime.textContent=`VOICE ${formatTime(speechElapsed)} / ${formatTime(speechDuration)}`;audioPlay.classList.toggle('playing',Boolean(currentUtterance)&&!speechPaused)}
function startSpeech(){if(!speechBlocks.length)return;window.speechSynthesis.cancel();speechPaused=false;clearInterval(speechTimer);speechTimer=setInterval(()=>{if(!speechPaused){speechElapsed=Math.min(speechDuration,speechElapsed+1);saveAudioPosition(activeDay,speechElapsed);updateSpeechUI()}},1000);speakBlock()}
function speakBlock(){if(speechIndex>=speechBlocks.length){finishSpeech();return}const block=speechBlocks[speechIndex];const u=new SpeechSynthesisUtterance(block.text);u.voice=naturalVoice(block.speaker);u.rate=block.speaker==='ARA'?0.93:0.96;u.pitch=block.speaker==='ARA'?1.02:.92;u.volume=1;u.onend=()=>{if(currentUtterance===u&&!speechPaused){speechIndex++;speakBlock()}};u.onerror=()=>{audioDeck.classList.add('disabled');clearInterval(speechTimer);currentUtterance=null;updateSpeechUI()};currentUtterance=u;window.speechSynthesis.speak(u);updateSpeechUI()}
function pauseSpeech(){speechPaused=true;window.speechSynthesis.pause();clearInterval(speechTimer);saveAudioPosition(activeDay,speechElapsed);updateSpeechUI()}
function resumeSpeech(){if(currentUtterance&&speechPaused){speechPaused=false;window.speechSynthesis.resume();clearInterval(speechTimer);speechTimer=setInterval(()=>{if(!speechPaused){speechElapsed=Math.min(speechDuration,speechElapsed+1);saveAudioPosition(activeDay,speechElapsed);updateSpeechUI()}},1000);updateSpeechUI()}else startSpeech()}
function stopSpeech(save=true){if(save&&speechMode)saveAudioPosition(activeDay,speechElapsed);clearInterval(speechTimer);speechTimer=null;currentUtterance=null;speechPaused=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();audioDeck?.classList.remove('speech');audioPlay?.classList.remove('playing')}
function finishSpeech(){clearInterval(speechTimer);currentUtterance=null;speechElapsed=0;saveAudioPosition(activeDay,0);if(!state.audioCompleted.includes(activeDay))state.audioCompleted.push(activeDay);state.checklist.listen=true;saveState();updateSpeechUI();renderMeters();if(state.view==='curr')renderCurr()}
audioPlay.addEventListener('click',()=>{if(audioDeck.classList.contains('disabled'))return;if(speechMode){if(currentUtterance&&!speechPaused)pauseSpeech();else resumeSpeech();return}if(audioElement.paused)audioElement.play().catch(()=>handleAudioUnavailable(activeDay));else audioElement.pause();updateAudioUI()});
audioElement.addEventListener('error',()=>handleAudioUnavailable(Number(audioElement.dataset.day)||activeDay));audioElement.addEventListener('play',updateAudioUI);audioElement.addEventListener('pause',updateAudioUI);audioElement.addEventListener('timeupdate',()=>{updateAudioUI();if(Math.floor(audioElement.currentTime)%5===0)saveAudioPosition(activeDay,audioElement.currentTime)});audioElement.addEventListener('ended',()=>{saveAudioPosition(activeDay,0);if(!state.audioCompleted.includes(activeDay))state.audioCompleted.push(activeDay);state.checklist.listen=true;saveState();updateAudioUI();renderMeters();if(state.view==='curr')renderCurr()});audioProgress.addEventListener('click',e=>{const rect=audioProgress.getBoundingClientRect();const pct=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));if(speechMode){speechElapsed=Math.floor(pct*speechDuration);speechIndex=0;while(speechIndex<speechBlocks.length-1&&blockStartSeconds(speechIndex+1)<speechElapsed)speechIndex++;if(currentUtterance){startSpeech()}else updateSpeechUI()}else if(audioElement.duration)audioElement.currentTime=pct*audioElement.duration;updateAudioUI()});function saveAudioPosition(dayNum,position){const next=Math.floor(position);if(state.audioPositions[dayNum]===next)return;state.audioPositions[dayNum]=next;saveState()}
syncAccess();updateAccountMode();render();stateStore.init();
